def parsegrid(block): return [[int(x) for x in l.split()] for l in block.strip().splitlines() if re.fullmatch(r'[0-9 ]+',l.strip())]
def components(g,bg):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for x in range(w):
   co=g[r][x]
   if co==bg or (r,x) in seen: continue
   st=[(r,x)];seen.add((r,x));p=[]
   while st:
    y,z=st.pop();p.append((y,z))
    for q in ((y+1,z),(y-1,z),(y,z+1),(y,z-1)):
     yy,xx=q
     if 0<=yy<h and 0<=xx<w and q not in seen and g[yy][xx]==co: seen.add(q);st.append(q)
   out.append((co,p))
 return out
def norm(p):
 y=min(a for a,b in p);x=min(b for a,b in p);return frozenset((a-y,b-x) for a,b in p)
def transforms(sh):
 out=[]
 for flip in [1,-1]:
  for k in range(4):
   pts=[]
   for y,x in sh:
    x*=flip
    for _ in range(k):y,x=x,-y
    pts.append((y,x))
