import sqlite3,re
p='/home/USER/continual-arc-baselines/.workbench/stage1/H-hermes-luna6-medium-fresh0/frozen/seen-reference/play/users/u070/system/state/hermes/state.db'
c=sqlite3.connect('file:'+p+'?mode=ro',uri=True)
sid='09fe4c3f-10db-4a4c-837c-6e0e6a86ba10'
for mid,txt in c.execute("select id,content from messages where session_id=? and role='user' and content like '%Demo pair%' order by id",(sid,)):
    pairs=re.findall(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n(.*?)\nDemo pair \1 output \(\2x\3\):\n(.*?)(?=\n\nSame instance|\Z)',txt,re.S)
    print('MESSAGE',mid,'pairs',len(pairs))
    for n,h,w,ins,outs in pairs:
        A=[list(map(int,x.split())) for x in ins.splitlines() if x.strip()]
        B=[list(map(int,x.split())) for x in outs.splitlines() if x.strip()]
        changes=[(r,col,A[r][col],B[r][col]) for r in range(len(A)) for col in range(len(A[0])) if A[r][col]!=B[r][col]]
        # component via 4-connectivity; gather same color
        def comps(g):
            seen=set(); out=[]
            for r,row in enumerate(g):
                for col,v in enumerate(row):
                    if v==4 or (r,col) in seen: continue
                    if v in (0,): pass
                    if (r,col) in seen: continue
                    q=[(r,col)]; seen.add((r,col)); cells=[]
                    while q:
                        y,x=q.pop(); cells.append((y,x))
                        for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                            if 0<=yy<len(g) and 0<=xx<len(row) and (yy,xx) not in seen and g[yy][xx]==v:
                                seen.add((yy,xx));q.append((yy,xx))
                    out.append((v,cells))
            return out
        cc=comps(A)
        # changed component matching any change coordinate
        print(' demo',n,'changes',len(changes),'values',set((x[2],x[3]) for x in changes),'coords',changes[:20])
        changed_coords={(r,col) for r,col,_,_ in changes}
        for v,cells in cc:
            if changed_coords.intersection(cells):
                print('  altered comp',v,'size',len(cells),'bbox',(min(r for r,c in cells),min(c for r,c in cells),max(r for r,c in cells),max(c for r,c in cells)),'coords',sorted(cells))

