import sqlite3,re,collections
p='/home/USER/continual-arc-baselines/.workbench/stage1/H-hermes-luna6-medium-fresh0/frozen/seen-reference/play/users/u070/system/state/hermes/state.db'; c=sqlite3.connect('file:'+p+'?mode=ro',uri=True); sid='09fe4c3f-10db-4a4c-837c-6e0e6a86ba10'
def extract(txt):
 m=re.search(r'Test input \((\d+)x(\d+)\):\n(.*?)(?=\nWrong attempts)',txt,re.S)
 return [list(map(int,l.split())) for l in m.group(3).splitlines()]
def getcomps(g):
 bg=collections.Counter(x for row in g for x in row).most_common(1)[0][0]; H=len(g);W=len(g[0]); seen=set(); out=[]
 for r in range(H):
  for x in range(W):
   v=g[r][x]
   if v==bg or (r,x) in seen: continue
