import sqlite3,re,collections
p='/home/USER/continual-arc-baselines/.workbench/stage1/H-hermes-luna6-medium-fresh0/frozen/seen-reference/play/users/u070/system/state/hermes/state.db'
c=sqlite3.connect(p); sid='09fe4c3f-10db-4a4c-837c-6e0e6a86ba10'
msgs=c.execute("select content from messages where session_id=? and role='user' order by id",(sid,)).fetchall()
for content, in msgs:
 for m in re.finditer(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n(.*?)\nDemo pair \1 output \(\d+x\d+\):\n(.*?)(?=\n\nSame instance|$)',content,re.S):
  n=int(m.group(1)); H,W=map(int,m.group(2,3));
  def grid(s): return [list(map(int,l.split())) for l in s.strip().splitlines()]
  a,b=grid(m.group(4)),grid(m.group(5)); dif=[(r,c,a[r][c],b[r][c]) for r in range(H) for c in range(W) if a[r][c]!=b[r][c]]
  bg=a[0][0]; seen=set(); comps=[]
  for r in range(H):
   for col in range(W):
    v=a[r][col]
    if v==bg or (r,col) in seen: continue
    stack=[(r,col)]; seen.add((r,col)); pts=[]
    while stack:
     x,y=stack.pop();pts.append((x,y))
     for z in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
      i,j=z
      if 0<=i<H and 0<=j<W and z not in seen and a[i][j]==v: seen.add(z);stack.append(z)
    comps.append((v,pts))
  def norm(pts):
   mr=min(x for x,y in pts); mc=min(y for x,y in pts); return frozenset((x-mr,y-mc) for x,y in pts)
  def transforms(sh):
   out=[]
   for refl in (1,-1):
    for rot in range(4):
     q=[]
     for x,y in sh:
      y*=refl
      for _ in range(rot): x,y=y,-x
      q.append((x,y))
     mx=min(x for x,y in q);my=min(y for x,y in q);out.append(frozenset((x-mx,y-my) for x,y in q))
   return set(out)
  ci=next(i for i,(v,pts) in enumerate(comps) if any((r,c) in pts for r,c,_,_ in dif))
  v,pts=comps[ci]; sh=norm(pts); tforms=transforms(sh)
  distances=[]
  for j,(w,other) in enumerate(comps):
   if j==ci: continue
   oh=norm(other); best=min(len(s^oh) for s in tforms)
   if best<=4: distances.append((best,w,len(other),sorted(oh),other))
  distances.sort(key=lambda x:(x[0],abs(len(pts)-x[2])))
  print('\nDEMO',n,'bg',bg,'changed',v,'size',len(pts),'bbox',max(x for x,y in pts)-min(x for x,y in pts)+1,max(y for x,y in pts)-min(y for x,y in pts)+1,'shape',sorted(sh),'difs',dif)
  print('near comps',[(d,w,z,s) for d,w,z,s,_ in distances[:8]])

